(()=>{'use strict';
const $=id=>document.getElementById(id),v=id=>$(id).value.trim(),pick=n=>document.querySelector(`input[name="${n}"]:checked`)?.value||'',money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const steps=[...document.querySelectorAll('.step')];let step=1,count=1,files=[],urls=[],briefId='';
const figures=()=>['Figurative / portrait','Pet / animal'].includes(pick('subject'));
function estimate(){let w,h;let size=pick('size');if(size==='custom'){let f=pick('units')==='cm'?1/2.54:1;w=Number(v('width'))*f;h=Number(v('height'))*f;}else if(size!=='help')[w,h]=size.split('x').map(Number);if(pick('orientation')==='Landscape'&&w<h||pick('orientation')==='Portrait'&&w>h)[w,h]=[h,w];let n=pick('panels')==='custom'?Number(v('quantity')):Number(pick('panels')),rate=pick('subject')==='Figurative / portrait'?3:2.5,extra=figures()?1+.25*(count-1):1,valid=Number.isFinite(w)&&Number.isFinite(h)&&w>=4&&h>=4&&w<=120&&h<=120&&Number.isInteger(n)&&n>=1&&n<=20,standard=valid?w*h*n*rate*extra:0,trade=Math.round(standard*.9),budget=pick('budget')==='custom'?Number(v('budget-amount')):pick('budget')==='help'?null:Number(pick('budget'));return{w,h,n,valid,standard,trade,budget,help:size==='help'};}
function dims(p){return p.help?'Dimensions to discuss':p.valid?`${Number(p.w.toFixed(1))} × ${Number(p.h.toFixed(1))} in per painting`:'Check custom dimensions';}
function update(){let p=estimate();$('figure-wrap').hidden=!figures();$('custom-size').hidden=pick('size')!=='custom';$('size-help').hidden=!p.help;$('quantity-wrap').hidden=pick('panels')!=='custom';$('custom-budget').hidden=pick('budget')!=='custom';$('date-wrap').hidden=pick('speed')==='Flexible';$('estimate-title').textContent=`${p.n} painting${p.n===1?'':'s'} · ${dims(p)}`;$('estimate-lines').replaceChildren();for(let[a,b]of [['Standard artwork',p.valid?money(p.standard):'Quote after sizing'],['Designer saving (10%)',p.valid?'−'+money(p.standard*.1):'Confirmed in quote'],['Framing, delivery & tax','Quoted separately']]){let d=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=a;dd.textContent=b;d.append(dt,dd);$('estimate-lines').append(d);}$('estimate').textContent=p.valid?money(p.trade):'To quote';$('deposit').textContent=p.valid?money(Math.ceil(p.trade/2)):'To quote';let s=$('budget-status');s.classList.remove('warn');if(!p.valid)s.textContent=p.help?'Kimberly will recommend dimensions and confirm your price.':'Check the dimensions and quantity.';else if(!p.budget)s.textContent='Kimberly can help plan your project budget.';else if(p.budget<p.trade){s.textContent=`Artwork estimate is ${money(p.trade-p.budget)} above your budget. Ask about a smaller size or fewer panels.`;s.classList.add('warn');}else s.textContent=pick('budget-scope')==='all'?`${money(p.budget-p.trade)} remains for framing, delivery and tax; final costs need a quote.`:'Artwork estimate fits your selected budget. Other costs are quoted separately.';$('due-today').textContent=p.valid?money(pick('plan')==='full'?p.trade:Math.ceil(p.trade/2)):'To discuss';if(step===5)review();}
function urlOK(s){try{return new URL(s).protocol==='https:';}catch{return false;}}
function validate(n){let e='',p=estimate();if(n===2){if((!p.valid&&!p.help)||!Number.isInteger(p.n)||p.n<1||p.n>20)e='Use dimensions from 4–120 inches (or equivalent) and 1–20 paintings.';if(pick('budget')==='custom'&&(!p.budget||p.budget<1||p.budget>1000000))e='Add your budget or choose “Help me plan”.';}if(n===3&&v('reference-link')&&!urlOK(v('reference-link')))e='Use a full https:// reference link, or leave it blank.';if(n===4){for(let id of ['name','firm','email','destination']){let good=!!v(id);$(id).setAttribute('aria-invalid',String(!good));if(!good)e='Add your name, design firm, email and destination for your booking.';}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v('email')))e='Enter a valid email address.';if(v('website')&&!urlOK(v('website')))e='Use a full https:// studio website, or leave it blank.';if(pick('speed')==='Installation date'&&!v('needby'))e='Choose an arrival date or a flexible timeline.';if(pick('speed')!=='Flexible'&&v('needby')){let today=new Date();today.setHours(0,0,0,0);if(new Date(v('needby')+'T23:59:59')<today)e='Choose an arrival date from today onward.';}}$('err-'+n).textContent=e;$('err-'+n).hidden=!e;return!e;}
function nav(){$('steps-nav').replaceChildren();steps.forEach((s,i)=>{let b=document.createElement('button');b.type='button';b.textContent=`${i+1}. ${s.dataset.name}`;if(i+1===step)b.setAttribute('aria-current','step');else if(i+1<step)b.className='done';else b.disabled=true;b.onclick=()=>go(i+1);$('steps-nav').append(b);});}
function go(n){step=n;steps.forEach((s,i)=>s.hidden=i+1!==n);$('done').hidden=true;$('steps-nav').hidden=false;nav();if(n===5)review();let h=steps[n-1].querySelector('h2');h.tabIndex=-1;h.focus({preventScroll:true});steps[n-1].scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
function rows(){let p=estimate();return[['Subject',pick('subject')+(figures()?` · ${count} subject(s) per painting`:'')],['Space',`${pick('type')} · ${pick('room')}`],['Artwork',`${p.n} painting(s) · ${dims(p)} · ${pick('orientation')}`],['Medium',pick('medium')],['Background',pick('background')],['Color direction',`${pick('palette')} · ${pick('mood')} · ${pick('matching')}`],['Physical swatch',pick('swatch')],['Reference details',v('reference')||'To discuss'],['Reference link',v('reference-link')||'Not supplied'],['References',files.length?files.map(f=>f.name).join(', ')+' — attach manually to your email':'Will send references later'],['Budget',`${p.budget?money(p.budget):'Help me plan'} · ${pick('budget-scope')==='all'?'Artwork, framing & delivery':'Artwork only'}`],['Artwork estimate',p.valid?`${money(p.trade)} after 10% trade saving; scope and eligibility to confirm`:'Quote after dimensions are agreed'],['50% artwork deposit',p.valid?`${money(Math.ceil(p.trade/2))} estimated (50%)`:'50% of agreed quote'],['Timeline',pick('speed')+(pick('speed')!=='Flexible'&&v('needby')?' · requested arrival '+v('needby'):'')],['Delivery',`${pick('delivery')} · ${v('destination')}`],['Finishing',pick('framing')],['Purchaser',pick('billing')],['Designer',`${v('name')} · ${v('firm')} · ${v('email')}`],['Studio website',v('website')||'Not supplied'],['Phone',v('phone')||'Not supplied'],['Tax document review',$('resale').checked?'Requested':'Not requested'],['Notes',v('notes')||'None']];}
function review(){let p=estimate();$('payment-choices').hidden=!p.valid;$('plan-deposit-amount').textContent=p.valid?money(Math.ceil(p.trade/2))+' now; remainder before shipping':'';$('plan-full-amount').textContent=p.valid?money(p.trade)+' artwork payment now':'';$('prepare').textContent=p.valid?'Continue to online booking':'Request sizing advice';$('booking-note').textContent=p.valid?'Pay online for your selected artwork. Framing, delivery, tax and special requests are additional where applicable and agreed separately before work starts. Kimberly will follow up for any missing details and confirm the production date.':'Your size is undecided, so no payment is requested yet. Send your selections and room references for sizing advice, then return to book online once you choose dimensions.';$('review').replaceChildren();for(let[a,b]of rows()){let d=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=a;dd.textContent=b;d.append(dt,dd);$('review').append(d);}}
function summary(){return[`DESIGNER PROJECT ${briefId}`,'Prepared locally — send these details to Kimberly. This document is not a payment receipt.','',...rows().map(([a,b])=>`${a}: ${b}`),'','Selected online payment: '+(estimate().valid?money(pick('plan')==='full'?estimate().trade:Math.ceil(estimate().trade/2)):'No payment until dimensions are selected')+'. Payment method: '+(pick('plan')==='full'?'Artwork in full':'50% artwork deposit')+'. Payment status: not verified here. Framing, delivery, taxes, rush and special materials additional where applicable.','Next: match online payment to these selections, confirm designer eligibility, color references and production date; any remaining artwork balance is due after final approval and before dispatch.','Physical swatches and agreed painted references guide color coordination; screen colors are approximate.'].join('\n');}
document.querySelectorAll('.next').forEach(b=>b.onclick=()=>{if(validate(step))go(step+1);});document.querySelectorAll('.back').forEach(b=>b.onclick=()=>go(step-1));$('designer-form').addEventListener('input',update);$('designer-form').addEventListener('change',update);$('designer-form').addEventListener('submit',e=>e.preventDefault());
$('count-minus').onclick=()=>{count=Math.max(1,count-1);$('count').textContent=count;update();};$('count-plus').onclick=()=>{count=Math.min(12,count+1);$('count').textContent=count;update();};
function renderFiles(){urls.forEach(URL.revokeObjectURL);urls=[];$('files-list').replaceChildren();files.forEach((f,i)=>{let d=document.createElement('div'),t=document.createElement('span'),b=document.createElement('button');t.textContent=f.name+' · attach to your email';b.type='button';b.textContent='Remove';b.setAttribute('aria-label','Remove '+f.name);b.onclick=()=>{files.splice(i,1);renderFiles();};if(f.type.startsWith('image/')){let im=document.createElement('img'),u=URL.createObjectURL(f);urls.push(u);im.src=u;im.alt='Selected reference: '+f.name;d.append(im);}d.append(t,b);$('files-list').append(d);});}
function addFiles(selected){let all=[...files,...selected];files=all.filter(f=>(f.type.startsWith('image/')||f.type==='application/pdf')&&f.size<=10*1024*1024).filter((f,i,a)=>a.findIndex(x=>x.name===f.name&&x.size===f.size)===i).slice(0,6);renderFiles();if(all.length>files.length){let p=document.createElement('p');p.className='hint';p.textContent='Some files were skipped: use up to 6 unique images or PDFs, 10 MB each.';$('files-list').append(p);}}
$('files').onchange=()=>{addFiles([...$('files').files]);$('files').value='';};$('drop').ondragover=e=>{e.preventDefault();$('drop').classList.add('over');};$('drop').ondragleave=()=>$('drop').classList.remove('over');$('drop').ondrop=e=>{e.preventDefault();$('drop').classList.remove('over');addFiles([...e.dataTransfer.files]);};
$('prepare').onclick=()=>{if(!$('agree').checked){$('err-5').hidden=false;return;}for(let n of [1,2,3,4])if(!validate(n)){go(n);return;}let d=new Date();briefId='KM-D-'+d.getFullYear()+String(d.getMonth()+1).padStart(2,'0')+String(d.getDate()).padStart(2,'0')+'-'+Math.random().toString(36).slice(2,6).toUpperCase();$('brief-id').textContent=briefId;let p=estimate();$('payment-step').hidden=!p.valid;$('payment-heading').textContent=pick('plan')==='full'?'Pay artwork in full':'Pay your 50% deposit';$('payment-amount').textContent=p.valid?money(pick('plan')==='full'?p.trade:Math.ceil(p.trade/2)):'';$('done-title').innerHTML=p.valid?'Book <em>your artwork</em>':'Get help <em>with sizing</em>';$('send-instructions').textContent=p.valid?'Email your booking details and reference files so Kimberly can connect your payment to your painting. Attach the originals; they are not attached automatically. Your details have not been sent yet.':'Email these selections and room references for sizing advice. No payment has been requested and your details have not been sent yet.';$('email-brief').href='mailto:kimberlysartandphotography@gmail.com?subject='+encodeURIComponent('Designer booking '+briefId+' · '+pick('room'))+'&body='+encodeURIComponent(summary());steps.forEach(s=>s.hidden=true);$('steps-nav').hidden=true;$('done').hidden=false;let h=$('done').querySelector('h2');h.tabIndex=-1;h.focus({preventScroll:true});$('done').scrollIntoView({block:'start'});};
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(summary());$('copy-note').textContent='Brief copied. Paste it into your email and attach the reference files.';}catch{$('copy-note').textContent='Copy is unavailable. Download the brief and attach it to your email.';}};
$('download').onclick=()=>{let u=URL.createObjectURL(new Blob([summary()],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=(briefId||'designer-project')+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),5000);};$('edit').onclick=()=>go(5);nav();update();
})();
